   229	                sc_pkcs15_wrap(p15card, obj, &target_key, wrap_flags[i],
   230	                        buf, &l, in, in_len);
   231	            }
   232	
   233	            int signature_flags[] = {SC_ALGORITHM_RSA_RAW,
   234	                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
   235	                SC_ALGORITHM_RSA_PAD_ISO9796,
   236	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA1,
   237	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA256,
   238	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA384,
   239	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA512,
   240	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA224,
   241	                SC_ALGORITHM_ECDSA_RAW, SC_ALGORITHM_ECDSA_HASH_SHA1,
   242	                SC_ALGORITHM_ECDSA_HASH_SHA224, SC_ALGORITHM_ECDSA_HASH_SHA256,
   243	                SC_ALGORITHM_ECDSA_HASH_SHA384, SC_ALGORITHM_ECDSA_HASH_SHA512,
   244	                SC_ALGORITHM_GOSTR3410_RAW, SC_ALGORITHM_GOSTR3410_HASH_GOSTR3411,
   245	                SC_ALGORITHM_GOSTR3410_HASHES,
   246	            };
   247	            for (i = 0; i < sizeof signature_flags/sizeof *signature_flags; i++) {
